BACK={'User':'workIssues WorkIssue[]\n crmLeads CrmLead[]\n crmActivities CrmActivity[]\n workProjects WorkProject[]\n workTasks WorkTask[]\n workEntries WorkTimeEntry[]\n posShifts PosShift[]\n posSales PosSale[]\n inspections ProductionOrder[]\n assignedTickets ServiceTicket[]','Customer':'crmLeads CrmLead[]\n workProjects WorkProject[]\n posSales PosSale[]\n subscriptions Subscription[]\n serviceTickets ServiceTicket[]\n invoices Invoice[]\n documents CommercialDocument[]','Product':'posLines PosSaleLine[]\n outputBoms BillOfMaterial[] @relation("BomOutput")\n bomComponents BomComponent[]\n productionOutputs ProductionOrder[] @relation("ProductionOutput")\n productionInputs ProductionInput[]\n subscriptions Subscription[]\n purchaseLines PurchaseLine[]\n invoiceLines InvoiceLine[]\n commercialLines CommercialLine[]\n movements StockMovement[]','Invoice':'workBills WorkBill[]\n subscriptionBills SubscriptionBill[]\n commercialDocs CommercialDocument[]'}
def foreign_key_indexes(fields):
 import re
 result=[]
 unique=[tuple(x.strip() for x in raw.split(',')) for raw in re.findall(r'@@(?:unique|index)\(\[([^]]+)\]\)',fields)]
 for raw in re.findall(r'@relation\([^\n]*?fields:\[([^]]+)\]',fields):
  names=tuple(x.strip() for x in raw.split(','))
  if names[0:1]!=('tenantId',) or len(names)<2 or names in result:continue
  if any(u[:len(names)]==names for u in unique):continue
  result.append(names)
 return result
def generate_schema(plan):
 tenant='model Tenant {\n id String @id @default(uuid())\n slug String @unique\n name String\n createdAt DateTime @default(now())\n'+''.join(' '+name[0].lower()+name[1:]+'Rows '+name+'[]\n' for name in MODELS)+'}\n'
 prisma='generator client {\n provider = "prisma-client-js"\n}\n datasource db {\n provider = "postgresql"\n}\n'+tenant
 for name,fields in MODELS.items():
  common=' id String @id @default(uuid())\n tenantId String\n tenant Tenant @relation(fields:[tenantId],references:[id])\n createdAt DateTime @default(now())\n updatedAt DateTime @updatedAt\n deletedAt DateTime?\n'
  prisma+='\nmodel '+name+' {\n'+common+' '+fields+'\n '+BACK.get(name,'')+'\n @@unique([tenantId,id])\n @@index([tenantId,createdAt])\n'+''.join(' @@index(['+','.join(index)+'])\n' for index in foreign_key_indexes(fields))+'}\n'
 sql='-- Run as migration owner; runtime erp_app role has no BYPASSRLS.\n'
 for name in MODELS:
  sql+=f'''ALTER TABLE "{name}" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "{name}" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "{name}" USING ("tenantId" = current_setting('app.tenant_id',true)) WITH CHECK ("tenantId" = current_setting('app.tenant_id',true));
'''
 sql+='''ALTER TABLE "Product" ADD CONSTRAINT nonnegative_product CHECK (quantity>=0 AND "unitMinor">=0);
ALTER TABLE "Invoice" ADD CONSTRAINT invoice_amounts CHECK ("subtotalMinor">=0 AND "taxMinor">=0 AND "totalMinor"="subtotalMinor"+"taxMinor");
ALTER TABLE "Payment" ADD CONSTRAINT payment_positive CHECK ("amountMinor">0);
ALTER TABLE "JournalLine" ADD CONSTRAINT journal_line_positive CHECK ("debitMinor">=0 AND "creditMinor">=0 AND NOT ("debitMinor">0 AND "creditMinor">0));
ALTER TABLE "InvoiceLine" ADD CONSTRAINT valid_invoice_line CHECK (quantity>0 AND "unitMinor">=0);
'''
 sql+='ALTER TABLE "CommercialLine" ADD CONSTRAINT valid_commercial_line CHECK (quantity>0 AND "unitMinor">=0);\nALTER TABLE "CommercialDocument" ADD CONSTRAINT valid_document_amounts CHECK ("subtotalMinor">=0 AND "taxMinor">=0 AND "totalMinor"="subtotalMinor"+"taxMinor" AND "taxBps">=0 AND "taxBps"<=10000);\n'
 sql+='ALTER TABLE "PurchaseLine" ADD CONSTRAINT valid_purchase_line CHECK (quantity>0 AND "unitMinor">=0);\nALTER TABLE "PurchaseOrder" ADD CONSTRAINT valid_purchase_amounts CHECK ("subtotalMinor">=0 AND "taxMinor">=0 AND "totalMinor"="subtotalMinor"+"taxMinor" AND "taxBps">=0 AND "taxBps"<=10000);\nALTER TABLE "VendorPayment" ADD CONSTRAINT vendor_payment_positive CHECK ("amountMinor">0);\n'
 sql+='ALTER TABLE "Subscription" ADD CONSTRAINT valid_subscription CHECK ("unitMinor">=0 AND "taxBps">=0 AND "taxBps"<=10000 AND status IN (\'ACTIVE\',\'PAUSED\',\'CANCELLED\'));\n'
 sql+='ALTER TABLE "BillOfMaterial" ADD CONSTRAINT bom_version_positive CHECK (version>0);\nALTER TABLE "BomComponent" ADD CONSTRAINT bom_component_positive CHECK (quantity>0 AND "unitCostMinor">=0);\nALTER TABLE "ProductionInput" ADD CONSTRAINT production_input_positive CHECK (quantity>0 AND "unitCostMinor">=0);\nALTER TABLE "ProductionOrder" ADD CONSTRAINT production_quantities_valid CHECK (quantity>0 AND "materialEstimateMinor">=0);\n'
 sql+="ALTER TABLE \"ProductionOrder\" ADD CONSTRAINT production_states_valid CHECK (status IN ('DRAFT','RELEASED','COMPLETED','CANCELLED') AND \"qualityStatus\" IN ('PENDING','PASSED','FAILED') AND (status!='COMPLETED' OR (\"qualityStatus\"='PASSED' AND \"completedAt\" IS NOT NULL)));\n"
 sql+="ALTER TABLE \"PosShift\" ADD CONSTRAINT shift_valid CHECK (\"openingMinor\">=0 AND status IN ('OPEN','CLOSED') AND ((status='OPEN' AND \"openKey\" IS NOT NULL AND \"openKey\"=\"cashierId\") OR (status='CLOSED' AND \"openKey\" IS NULL AND \"closedAt\" IS NOT NULL AND \"expectedClosingMinor\" IS NOT NULL AND \"countedClosingMinor\" IS NOT NULL AND \"varianceMinor\" IS NOT NULL AND \"expectedClosingMinor\">=0 AND \"countedClosingMinor\">=0 AND \"varianceMinor\"=\"countedClosingMinor\"-\"expectedClosingMinor\")));\n"
 sql+='ALTER TABLE "PosSale" ADD CONSTRAINT pos_sale_valid CHECK ("subtotalMinor">=0 AND "taxMinor">=0 AND "totalMinor"="subtotalMinor"+"taxMinor" AND "tenderedMinor">="totalMinor" AND "changeMinor"="tenderedMinor"-"totalMinor" AND "taxBps">=0 AND "taxBps"<=10000);\nALTER TABLE "PosSaleLine" ADD CONSTRAINT pos_sale_line_valid CHECK (quantity>0 AND "unitMinor">=0);\nALTER TABLE "PosRefund" ADD CONSTRAINT pos_refund_valid CHECK ("amountMinor">=0);\n'
 sql+="ALTER TABLE \"CrmLead\" ADD CONSTRAINT lead_valid CHECK (stage IN ('NEW','QUALIFIED','WON','LOST') AND (\"potentialMinor\" IS NULL OR \"potentialMinor\">=0) AND (stage!='WON' OR \"customerId\" IS NOT NULL));\nALTER TABLE \"CrmActivity\" ADD CONSTRAINT crm_activity_valid CHECK (kind IN ('CALL','NOTE','MEETING','FOLLOW_UP'));\nALTER TABLE \"WorkProject\" ADD CONSTRAINT project_valid CHECK (status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED') AND (\"budgetMinor\" IS NULL OR \"budgetMinor\">=0) AND (\"startsOn\" IS NULL OR \"dueOn\" IS NULL OR \"dueOn\">=\"startsOn\"));\nALTER TABLE \"WorkTask\" ADD CONSTRAINT work_task_valid CHECK (status IN ('TODO','IN_PROGRESS','BLOCKED','DONE','CANCELLED'));\nALTER TABLE \"WorkTimeEntry\" ADD CONSTRAINT work_time_valid CHECK (\"endedAt\">\"startedAt\" AND \"durationSeconds\">0 AND \"durationSeconds\"<=86400 AND EXTRACT(EPOCH FROM (\"endedAt\"-\"startedAt\"))=\"durationSeconds\" AND (\"voidedAt\" IS NULL OR \"voidReason\" IS NOT NULL));\n"
 sql+='ALTER TABLE "WorkBill" ADD CONSTRAINT work_bill_tax CHECK ("taxBps">=0 AND "taxBps"<=10000);\nALTER TABLE "WorkBillLine" ADD CONSTRAINT work_bill_line_valid CHECK ("durationSeconds">0 AND "durationSeconds"<=86400 AND "rateMinorPerHour">0 AND "amountMinor">=0 AND "amountMinor"=FLOOR(("durationSeconds"::numeric*"rateMinorPerHour"+1800)/3600));\n'
 sql+="ALTER TABLE \"WorkMilestone\" ADD CONSTRAINT milestone_valid CHECK (status IN ('PENDING','REACHED','CANCELLED') AND (status!='REACHED' OR \"reachedAt\" IS NOT NULL));\nALTER TABLE \"WorkIssue\" ADD CONSTRAINT work_issue_valid CHECK (status IN ('OPEN','IN_PROGRESS','RESOLVED','CLOSED') AND priority IN ('LOW','NORMAL','HIGH','CRITICAL') AND (status NOT IN ('RESOLVED','CLOSED') OR (resolution IS NOT NULL AND \"resolvedAt\" IS NOT NULL)) AND (status!='CLOSED' OR \"closedAt\" IS NOT NULL));\n"
 sql+="ALTER TABLE \"PurchaseRfq\" ADD CONSTRAINT rfq_valid CHECK (status IN ('OPEN','AWARDED','CANCELLED') AND currency ~ '^[A-Z]{3}$');\nALTER TABLE \"RfqLine\" ADD CONSTRAINT rfq_line_valid CHECK (quantity>0 AND quantity<=1000000);\nALTER TABLE \"RfqOffer\" ADD CONSTRAINT rfq_offer_valid CHECK (status IN ('ACTIVE','WITHDRAWN') AND \"taxBps\">=0 AND \"taxBps\"<=10000 AND \"deliveryDays\">=0 AND \"deliveryDays\"<=3650 AND \"subtotalMinor\">=0 AND \"taxMinor\">=0 AND \"totalMinor\"=\"subtotalMinor\"+\"taxMinor\" AND ((status='ACTIVE' AND \"activeKey\"=\"supplierId\" AND \"activeKey\" IS NOT NULL) OR (status='WITHDRAWN' AND \"activeKey\" IS NULL AND \"withdrawnAt\" IS NOT NULL AND \"withdrawalReason\" IS NOT NULL)));\nALTER TABLE \"RfqOfferLine\" ADD CONSTRAINT rfq_offer_line_valid CHECK (quantity>0 AND \"unitMinor\">=0);\n"
 erd='erDiagram\n Tenant ||--o{ User : contains\n Tenant ||--o{ Customer : owns\n Customer ||--o{ Invoice : billed\n Invoice ||--o{ InvoiceLine : contains\n Invoice ||--o{ Payment : receives\n Product ||--o{ StockMovement : records\n Journal ||--|{ JournalLine : balances\n LedgerAccount ||--o{ JournalLine : posts\n'
 return {'prisma':prisma,'tenant_policies_sql':sql,'erd':erd,'models':list(MODELS),'specialty_modules':[m['id'] for m in plan['modules'] if m['runtime']!='core_starter'],'specialty_domain_schema':'ISP billing/tickets, basic BOM/production, cash POS, CRM and project/time billing source included; other specialty schemas not generated; BusinessRecord is not a clinical/banking transaction engine','tenant_isolation':'RLS + composite foreign keys + application-scoped transactions'}
